  VcsOperationsStatusRunning -> "running"
  VcsOperationsStatusSuccess -> "success"
  VcsOperationsStatusError -> "error"

parseVcsOperationsStatus :: Text -> Either Text VcsOperationsStatus
parseVcsOperationsStatus value = case value of
  "pending" -> Right VcsOperationsStatusPending
  "running" -> Right VcsOperationsStatusRunning
  "success" -> Right VcsOperationsStatusSuccess
  "error" -> Right VcsOperationsStatusError
  _ -> Left (T.append "unsupported vcs_operations.status: " value)

data VcsOperationsRow = VcsOperationsRow
  { vcsOperationsId :: Text
  , vcsOperationsRepositoryId :: (Maybe Text)
  , vcsOperationsVcsKind :: Text
  , vcsOperationsOpType :: Text
  , vcsOperationsStatus :: Text
  , vcsOperationsParams :: Text
  , vcsOperationsResultSummary :: Text
  , vcsOperationsError :: (Maybe Text)
  , vcsOperationsDurationMs :: (Maybe Int)
  , vcsOperationsRequestedBy :: (Maybe Text)
  , vcsOperationsCreatedAt :: Text
  , vcsOperationsUpdatedAt :: Text
  } deriving (Eq, Show)

instance FromRow VcsOperationsRow where
  fromRow = VcsOperationsRow <$> field <*> field <*> field <*> field <*> field <*> field <*> field <*> field <*> field <*> field <*> field <*> field

validateVcsOperationsDurationMs :: Int -> Either Text Int
validateVcsOperationsDurationMs value
  | value < 0 = Left "vcs_operations.duration_ms is below the minimum"
  | otherwise = Right value

validateVcsOperationsRequestedBy :: Text -> Either Text Text
validateVcsOperationsRequestedBy value
  | T.length value > 200 = Left "vcs_operations.requested_by must be at most 200 characters"
  | otherwise = Right value
